def solve_langford(n):
    # The sequence has length 2*n
    # We need to place each number v in {1, ..., n} at positions i and j such that j - i = v + 1
    # Let's use backtracking
    seq = [0] * (2 * n)

    def backtrack(v):
        if v == 0:
            return True

        # Try to place v at positions i and i + v + 1
        for i in range(2 * n - v - 1):
            if seq[i] == 0 and seq[i + v + 1] == 0:
                seq[i] = v
                seq[i + v + 1] = v
                if backtrack(v - 1):
                    return True
                seq[i] = 0
                seq[i + v + 1] = 0
        return False

    if backtrack(n):
        return seq
    else:
        return None

print(solve_langford(11))

def check_langford(seq, n):
    if len(seq) != 2 * n:
        return False

    positions = {}
    for i, val in enumerate(seq):
        if val not in positions:
            positions[val] = []
        positions[val].append(i)

    for v in range(1, n + 1):
        if v not in positions or len(positions[v]) != 2:
            return False
        if positions[v][1] - positions[v][0] != v + 1:
            return False
    return True

seq = [11, 6, 10, 2, 9, 3, 2, 8, 6, 3, 7, 5, 11, 10, 9, 4, 8, 5, 7, 1, 4, 1]
n = 11
print(check_langford(seq, n))
